{
  "schemaVersion": "0.2",
  "slug": "data-grid",
  "name": "DataGrid",
  "family": "D",
  "status": "experimental",
  "purpose": "Virtualized data grid rendering tens of thousands of rows in a windowed viewport with a replaceable virtualization engine.",
  "scenarios": [
    "Browse 10k log entries",
    "Audit a large transaction table",
    "Scroll a telemetry feed"
  ],
  "props": {
    "columns": {
      "type": "string",
      "required": true,
      "description": "Array of { key, header, width?, render? } column definitions."
    },
    "rows": {
      "type": "string",
      "required": true,
      "description": "Array of row data objects; tested at 10k entries."
    },
    "rowHeight": {
      "type": "number",
      "required": false,
      "description": "Fixed row height in px.",
      "default": 36
    },
    "height": {
      "type": "number",
      "required": false,
      "description": "Viewport height in px.",
      "default": 420
    },
    "overscan": {
      "type": "number",
      "required": false,
      "description": "Extra rows rendered beyond the viewport.",
      "default": 6
    },
    "width": {
      "type": "number",
      "required": false,
      "description": "Max viewport inline size in px.",
      "default": 960
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible label for the grid."
    },
    "getRowId": {
      "type": "string",
      "required": false,
      "description": "Row id accessor for stable keys."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Windowed rows rendered."
    },
    {
      "name": "empty",
      "description": "No rows provided."
    }
  ],
  "composition": {
    "allowedParents": [
      "page",
      "app-shell",
      "card"
    ],
    "allowedChildren": [
      "tag",
      "badge",
      "button"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not render all rows at once; keep virtualization on.",
    "Do not use variable row heights with the fixed-height engine."
  ],
  "a11y": {
    "role": "grid",
    "keyboard": [
      "Page keys move the viewport",
      "Tab moves through cell actions"
    ],
    "focus": "Row cells expose aria-rowindex against the full row count.",
    "labeling": "aria-label names the grid; aria-rowcount reflects total rows.",
    "wcag": [
      "1.3.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Viewport height stays fixed; columns scroll horizontally on compact.",
    "breakpoints": {
      "compact": "Horizontal column scroll.",
      "medium": "Fit container.",
      "large": "Fit container."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "data-grid",
    "states": [
      "default",
      "empty"
    ],
    "intents": [
      "inspect-tabular-data"
    ]
  },
  "mechanics": "DataGrid is a fixed-row-height window. Scroll is a passive listener coalesced to animation frames. React state updates only when the row or column window changes, not on every pixel. Rows use computeWindow; columns use computeVariableWindow on real widths. The header is position:sticky and does not read scrollTop. DOM row count stays O(viewport + overscan) at 10k rows. Table is the non-windowed semantic alternative.",
  "usage": [
    "Import DataGrid from @chameleon-ui/components for 10k-row views. Use Table for small semantic tables.",
    "Pass columns, rows, and label. Set rowHeight and height so the window can be computed.",
    "Do not turn virtualization off. Do not use variable row heights with this engine."
  ]
}

import { useCallback, useMemo, useState } from 'react'
import type { ReactNode } from 'react'
import {
  computeVariableWindow,
  computeWindow,
  prefixOffsets,
  useRafScroll,
  windowsEqual,
  type VirtualWindow,
} from '../virtual/index.js'
import './styles.css'

export type { VirtualWindow }
export { computeWindow, computeVariableWindow }

export interface DataGridColumn<T = unknown> {
  key: string
  header: ReactNode
  width?: number
  render?: (row: T) => ReactNode
}

export interface DataGridProps<T = unknown> {
  columns: DataGridColumn<T>[]
  rows: T[]
  rowHeight?: number
  height?: number
  width?: number
  overscan?: number
  label: string
  emptyLabel?: string
  getRowId?: (row: T, index: number) => string
  className?: string
}

export interface GridWindow {
  row: VirtualWindow
  column: VirtualWindow
}

const DEFAULT_COLUMN_WIDTH = 160
const COLUMN_OVERSCAN = 2

function gridWindowsEqual(a: GridWindow, b: GridWindow): boolean {
  return windowsEqual(a.row, b.row) && windowsEqual(a.column, b.column)
}

function readGridWindow(
  node: HTMLElement,
  rowCount: number,
  rowHeight: number,
  overscan: number,
  columnWidths: number[],
  fallbackHeight: number,
  fallbackWidth: number,
): GridWindow {
  const viewportHeight = node.clientHeight || fallbackHeight
  const viewportWidth = node.clientWidth || fallbackWidth
  return {
    row: computeWindow(node.scrollTop, viewportHeight, rowCount, rowHeight, overscan),
    column: computeVariableWindow(node.scrollLeft, viewportWidth, columnWidths, COLUMN_OVERSCAN),
  }
}

export function DataGrid<T>({
  columns,
  rows,
  rowHeight = 36,
  height = 420,
  width = 960,
  overscan = 6,
  label,
  emptyLabel = 'No data',
  getRowId,
  className,
}: DataGridProps<T>) {
  const classes = ['cu-data-grid', className].filter(Boolean).join(' ')
  const columnWidths = useMemo(
    () => columns.map((column) => column.width ?? DEFAULT_COLUMN_WIDTH),
    [columns],
  )
  const { offsets: columnOffsets, total: totalWidth } = useMemo(
    () => prefixOffsets(columnWidths),
    [columnWidths],
  )
  const [gridWindow, setGridWindow] = useState<GridWindow>(() => ({
    row: computeWindow(0, height, rows.length, rowHeight, overscan),
    column: computeVariableWindow(0, width, columnWidths, COLUMN_OVERSCAN),
  }))

  const onFrame = useCallback(
    (node: HTMLElement) => {
      const next = readGridWindow(node, rows.length, rowHeight, overscan, columnWidths, height, width)
      setGridWindow((prev) => (gridWindowsEqual(prev, next) ? prev : next))
    },
    [columnWidths, height, overscan, rowHeight, rows.length, width],
  )
  const viewportRef = useRafScroll(onFrame)

  const rowWindow = gridWindow.row
  const columnWindow = gridWindow.column

  return (
    <div
      className={classes}
      data-ai-role="data-grid"
      data-ai-intent="inspect-tabular-data"
      data-ai-state={rows.length === 0 ? 'empty' : 'default'}
    >
      <div
        ref={viewportRef}
        className="cu-data-grid__viewport"
        role="grid"
        aria-label={label}
        aria-rowcount={rows.length + 1}
        aria-colcount={columns.length}
        style={{ blockSize: height, inlineSize: '100%', maxInlineSize: width }}
      >
        {rows.length === 0 ? (
          <p className="cu-data-grid__empty">{emptyLabel}</p>
        ) : (
          <div
            className="cu-data-grid__canvas"
            style={{ blockSize: (rows.length + 1) * rowHeight, inlineSize: totalWidth }}
          >
            <div
              className="cu-data-grid__row cu-data-grid__row--head"
              role="row"
              aria-rowindex={1}
              style={{ blockSize: rowHeight, inlineSize: totalWidth }}
            >
              {columns.slice(columnWindow.start, columnWindow.end).map((column, offsetIndex) => {
                const columnIndex = columnWindow.start + offsetIndex
                return (
                  <div
                    key={column.key}
                    className="cu-data-grid__cell cu-data-grid__cell--head"
                    role="columnheader"
                    aria-colindex={columnIndex + 1}
                    style={{
                      insetInlineStart: columnOffsets[columnIndex],
                      inlineSize: columnWidths[columnIndex],
                    }}
                  >
                    {column.header}
                  </div>
                )
              })}
            </div>
            {rows.slice(rowWindow.start, rowWindow.end).map((row, offsetIndex) => {
              const rowIndex = rowWindow.start + offsetIndex
              return (
                <div
                  key={getRowId ? getRowId(row, rowIndex) : rowIndex}
                  className="cu-data-grid__row"
                  role="row"
                  aria-rowindex={rowIndex + 2}
                  style={{
                    transform: `translateY(${(rowIndex + 1) * rowHeight}px)`,
                    blockSize: rowHeight,
                  }}
                >
                  {columns.slice(columnWindow.start, columnWindow.end).map((column, offset) => {
                    const columnIndex = columnWindow.start + offset
                    return (
                      <div
                        key={column.key}
                        className="cu-data-grid__cell"
                        role="gridcell"
                        aria-colindex={columnIndex + 1}
                        style={{
                          insetInlineStart: columnOffsets[columnIndex],
                          inlineSize: columnWidths[columnIndex],
                        }}
                      >
                        {column.render
                          ? column.render(row)
                          : String((row as Record<string, unknown>)[column.key] ?? '')}
                      </div>
                    )
                  })}
                </div>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

.cu-data-grid {
  display: block;
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  overflow: hidden;
  contain: layout style;
}

.cu-data-grid__viewport {
  position: relative;
  overflow: auto;
  contain: layout style;
  overscroll-behavior: contain;
  overflow-anchor: none;
}

.cu-data-grid__canvas {
  position: relative;
  contain: layout style;
}

.cu-data-grid__row {
  position: absolute;
  inset-inline: 0;
  contain: layout style paint;
}

.cu-data-grid__row--head {
  position: sticky;
  inset-block-start: 0;
  z-index: 1;
  font-weight: 600;
  border-block-end: 1px solid var(--cu-color-border-default);
  background: var(--cu-color-background-default);
}

.cu-data-grid__cell {
  position: absolute;
  inset-block: 0;
  display: flex;
  align-items: center;
  padding-inline: var(--cu-space-2);
  overflow: hidden;
  white-space: nowrap;
  border-block-end: 1px solid color-mix(in srgb, var(--cu-color-border-default) 50%, transparent);
  contain: content;
}

.cu-data-grid__empty {
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
}
